package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import android.graphics.*;import java.util.*;import java.io.*;
/** Regression for text-column centering and paragraph-end comment placement. */
public final class AlignmentChecks extends DeviceChecks {
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"alignment-evidence");output.mkdirs();Bundle result=new Bundle();try{ReaderSettings settings=new ReaderSettings(getTargetContext());settings.font=22;settings.comments=true;float density=getTargetContext().getResources().getDisplayMetrics().density;ReaderPaginator layout=new ReaderPaginator(repeat("左右边距需要相同，正文不应为段评单独缩窄。",20),"章节标题",1080,1920,density,density,settings);float left=layout.left,right=1080-left-layout.pages.get(0).fragments.get(0).layout.getWidth();record("text_column_margins_dp",new JSONObject().put("left",left/density).put("right",right/density).put("center_shift",(left-right)/2/density));assertTrue(Math.abs(left-right)<=1,"正文左右边距必须相同；当前左 "+left/density+"dp，右 "+right/density+"dp");record("symmetric_text_column",true);geometry();ink();if("visual".equals(args.getString("phase")))visual();result.putString("stream","PASS\n");save(null);finish(Activity.RESULT_OK,result);}catch(Throwable e){try{record("failure",android.util.Log.getStackTraceString(e));save(e);}catch(Exception ignored){}result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}

 void geometry()throws Exception{
 int tested=0,bubbles=0,wrapped=0;float density=getTargetContext().getResources().getDisplayMetrics().density,scaled=getTargetContext().getResources().getDisplayMetrics().scaledDensity;
 for(int font:new int[]{16,19,20,22,29,30})for(int spacing:new int[]{0,1,2}){
 ReaderSettings on=new ReaderSettings(getTargetContext());on.comments=true;on.font=font;on.spacing=spacing;ReaderSettings off=new ReaderSettings(getTargetContext());off.comments=false;off.font=font;off.spacing=spacing;
 for(String text:new String[]{"短句。",repeat("汉",30),repeat("长段落保证文字连续且段评不遮挡。",70)+"末。","对话。\n\n第二段。\n\n"+repeat("汉",38),"含 emoji😀 与生僻字𠀀。"+repeat("连续正文。",60),"段末emoji😀"}){
 ReaderPaginator a=new ReaderPaginator(text,"章节标题",1080,1920,density,scaled,on),b=new ReaderPaginator(text,"章节标题",1080,1920,density,scaled,off);coverage(a);coverage(b);assertTrue(a.heading.getWidth()==b.heading.getWidth(),"no global comment gutter");Map<Integer,android.text.StaticLayout> before=new HashMap<>();for(ReaderPaginator.Page page:b.pages)for(ReaderPaginator.Fragment f:page.fragments)before.put(f.paragraphStart,f.layout);
 Map<Integer,Integer> endings=new HashMap<>();for(int pageIndex=0;pageIndex<a.pages.size();pageIndex++){
 Bitmap bitmap=Bitmap.createBitmap(1080,1920,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);a.draw(new Canvas(bitmap),pageIndex,Color.BLACK);
 ReaderPaginator.Page page=a.pages.get(pageIndex);for(int i=0;i<page.fragments.size();i++){
 ReaderPaginator.Fragment f=page.fragments.get(i);assertTrue(Math.abs(a.left-(1080-a.left-f.layout.getWidth()))<=1,"centered text");assertTrue(f.layout.getText().toString().equals(text.substring(f.paragraphStart,f.paragraphEnd)),"original text and offsets never include placeholders");RectF rect=a.commentBubble(f);if(rect==null)continue;
 endings.put(f.paragraphStart,endings.getOrDefault(f.paragraphStart,0)+1);if(f.layout.getLineCount()>before.get(f.paragraphStart).getLineCount())wrapped++;bubbles++;
 assertTrue(rect.left>=a.left-1&&rect.right<=1080-a.left+1,"bubble within text margins");assertTrue(rect.bottom<=a.bottom+1,"bubble above footer");
 for(int y=Math.max(0,(int)rect.top);y<Math.min(1920,(int)rect.bottom);y++)for(int x=Math.max(0,(int)rect.left);x<Math.min(1080,(int)rect.right);x++)assertTrue(Color.red(bitmap.getPixel(x,y))>200,"actual text pixels never covered by bubble");
 if(i+1<page.fragments.size())assertTrue(rect.bottom<page.fragments.get(i+1).y,"no overlap with next paragraph");
 }bitmap.recycle();}
 for(int count:endings.values())assertTrue(count==1,"one bubble at paragraph end across pages");tested++;}}
 assertTrue(wrapped>0,"full final lines wrap with bubble reservation");record("font_spacing_paragraph_geometry_matrix",new JSONObject().put("layouts",tested).put("inline",bubbles).put("wrapped_endings",wrapped));
 assertTrue("998".equals(ReaderSurface.commentLabel(998))&&"999+".equals(ReaderSurface.commentLabel(999))&&"1万".equals(ReaderSurface.commentLabel(10000))&&"7.9万".equals(ReaderSurface.commentLabel(78900))&&"10万".equals(ReaderSurface.commentLabel(100000))&&"百万".equals(ReaderSurface.commentLabel(1000000)),"reference count formats");record("reference_count_boundaries",true);
 }
 void ink()throws Exception{int checked=0;float density=getTargetContext().getResources().getDisplayMetrics().density,scaled=getTargetContext().getResources().getDisplayMetrics().scaledDensity;for(int font:new int[]{16,20,22,23,30})for(boolean serif:new boolean[]{false,true})for(int width:new int[]{720,1080,1440}){ReaderSettings settings=new ReaderSettings(getTargetContext());settings.font=font;settings.serif=serif;settings.comments=true;ReaderPaginator layout=new ReaderPaginator(repeat("汉",600),"标题",width,1920,density,scaled,settings);Bitmap bitmap=Bitmap.createBitmap(width,1920,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);layout.draw(new Canvas(bitmap),1,Color.BLACK);int[] pixels=new int[width*1920];bitmap.getPixels(pixels,0,width,0,0,width,1920);int min=width,max=-1;for(int y=(int)layout.top;y<layout.bottom;y++)for(int x=0;x<width;x++){int pixel=pixels[y*width+x];if(Color.red(pixel)<100&&Color.green(pixel)<100&&Color.blue(pixel)<100){min=Math.min(min,x);max=Math.max(max,x);}}bitmap.recycle();int right=width-1-max;float drift=(min-right)/2f;assertTrue(max>=min,"rendered text pixels");if(font==22&&!serif&&width==1080)record("actual_glyph_edges_22sp",new JSONObject().put("left_px",min).put("right_px",right).put("shift_px",drift));assertTrue(Math.abs(min-right)<=2*density,"actual glyph column must be centered: font="+font+" serif="+serif+" width="+width+" left="+min+" right="+right);coverage(layout);checked++;}record("actual_glyph_pixel_matrix",checked);}
 void visual()throws Exception{LocalLibrary library=new LocalLibrary(getTargetContext());Book selected=library.books(true).get(0);JSONObject original=library.progress(selected.id);assertTrue(original!=null,"user reading position");long lastRead;try(android.database.Cursor c=library.getReadableDatabase().rawQuery("SELECT last_read FROM books WHERE id=?",new String[]{selected.id})){c.moveToFirst();lastRead=c.getLong(0);}try{launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",selected.id).putExtra("book_name",selected.title).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();assertTrue(reader.anchor==original.optInt("offset"),"exact original text offset restored");shot("current-user-fixed");int page=reader.surface.frame.pageIndex;String chapter=reader.chapter.optString("id");float w=reader.surface.getWidth(),h=reader.surface.getHeight();assertTrue(page+1<reader.surface.frame.layout.pages.size(),"fixture has next page");swipe(w*.85f,h*.5f,w*.2f,h*.5f,380);waitFor(()->!reader.surface.animating(),4,"actual forward swipe");assertTrue(reader.surface.frame.pageIndex==page+1&&reader.comments.layer==null,"forward swipe with inline bubbles");shot("current-user-next");swipe(w*.2f,h*.5f,w*.85f,h*.5f,380);waitFor(()->!reader.surface.animating(),4,"actual back swipe");assertTrue(reader.surface.frame.pageIndex==page&&reader.chapter.optString("id").equals(chapter),"back to same chapter and page");record("current_user_chapter_and_gestures",new JSONObject().put("title",reader.chapter.optString("title")).put("font",reader.settings.font).put("page",page+1).put("original_offset",original.optInt("offset")).put("left_dp",reader.surface.frame.layout.left/getTargetContext().getResources().getDisplayMetrics().density));}finally{if(reader!=null)ui(()->reader.finish());library.progress(selected.id,original.optString("chapter"),original.optInt("offset"),original.optInt("index"),original.optInt("total"),original.optString("title"));ContentValues v=new ContentValues();v.put("last_read",lastRead);library.getWritableDatabase().update("books",v,"id=?",new String[]{selected.id});}assertTrue(library.progress(selected.id).optInt("offset")==original.optInt("offset"),"original position retained after visual test");record("user_position_preserved",true);}
 void save(Throwable error)throws Exception{try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(output,"results.json")),"UTF-8")){out.write(new JSONObject().put("success",error==null).put("checks",checks).toString(2));}}
}
